#include <set>
#define main jointBaselineMain
#include "joint.cpp"
#undef main
struct Candidate{float sc;Key key;bool operator<(const Candidate&b)const{return sc>b.sc;}};
int main(int argc,char**argv){load(argv[1]);ifstream in(argv[2]),kf(argv[3]),lf(argv[4]);int n;string s;while(in>>n>>s)payloads.push_back({n,s});Keys truth,start;for(int j=0;j<3;j++){truth[j].resize(j==0?21:j==1?19:20);for(int&v:truth[j])kf>>v;}while(getline(lf,s))if(s.rfind("BEST ",0)==0)break;for(int j=0;j<3;j++){start[j].resize(truth[j].size());for(int&v:start[j])lf>>v;}Keys current=start;float sc=objective(current);cout<<"initial "<<sc<<" truth "<<objective(truth)<<'\n';for(int pass=0;pass<20;pass++){array<vector<Candidate>,3> pools;Keys win=current;float top=sc;for(int j=0;j<3;j++){int w=current[j].size();set<Key>seen;auto evaluate=[&](Key k){canon(k);if(!seen.insert(k).second)return;Keys proposal=current;proposal[j]=k;float z=objective(proposal);pools[j].push_back({z,k});if(z>top+.001){top=z;win=proposal;}};for(int a=0;a<w;a++)for(int b=a+1;b<w;b++){auto k=current[j];swap(k[a],k[b]);evaluate(k);}for(int a=0;a<w;a++)for(int b=a+1;b<w;b++)for(int c=b+1;c<=w;c++){auto k=current[j];rotate(k.begin()+a,k.begin()+b,k.begin()+c);evaluate(k);}sort(pools[j].begin(),pools[j].end());pools[j].resize(min((int)pools[j].size(),12));}for(int j=0;j<3;j++)for(int l=j+1;l<3;l++)for(auto a:pools[j])for(auto b:pools[l]){Keys candidate=current;candidate[j]=a.key;candidate[l]=b.key;float z=objective(candidate);if(z>top+.001){top=z;win=candidate;}}cout<<"pass "<<pass<<" "<<top<<'\n'<<flush;if(top<=sc+.001)break;current=win;sc=top;}auto actual=plain(current),want=plain(truth);int match=0;for(int m=0;m<actual.size();m++)for(int i=0;i<actual[m].size();i++)match+=actual[m][i]==want[m][i];cout<<"matches "<<match<<"/250 keys "<<(current==truth)<<'\n';for(auto k:current){for(int v:k)cout<<v<<' ';cout<<'\n';}for(auto p:actual)cout<<p<<'\n';}
